<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { createLayoutEditor, type LayoutRule, type Selection } from './layout-editor'
import adoptedAndroidLayout from './presets/android-user-layout.json'
import spacingLayout from './presets/android-spacing-layout.json'
import stateLayout from './presets/android-state-layout.json'
import positionLayout from './presets/android-position-layout.json'
import deviceTestLayout from './presets/android-device-test-layout.json'
import { adoptSourceBaseline, sourceBaseline } from './source-baseline'
import TypographyTools from './TypographyTools.vue'
import { typographyKeys, validTypography, type TypographyKey } from './typography'
const props=defineProps<{frame?:HTMLIFrameElement;root?:HTMLElement;surface:string;locked:boolean;viewport:{width:number;height:number};storageKey?:string}>()
const emit=defineEmits<{selection:[value:Selection|null];viewport:[value:{width:number;height:number}]}>()
const key=props.storageKey||'clash-component-layout-v1'
try{adoptSourceBaseline(localStorage,key)}catch{/* Keep existing overrides when a safe backup cannot be written. */}
function valid(value:unknown):value is LayoutRule[]{return Array.isArray(value)&&value.length<2000&&value.every(r=>r&&['context','isolated'].includes(r.surface)&&/^[a-z-]+$/.test(r.page)&&typeof r.selector==='string'&&!/[{}]/.test(r.selector)&&r.styles&&Object.entries(r.styles).every(([k,v])=>(typeof v==='string'&&(typographyKeys as readonly string[]).includes(k))?validTypography(k,v):['left','top','position','width','height','box-sizing','min-width','min-height','max-width','max-height','flex-shrink','display','right','bottom','margin-left','margin-right','margin-top','margin-bottom'].includes(k)&&typeof v==='string'&&/^-?[\d.]+px$|^(relative|absolute|fixed|sticky|border-box|none|inline-block|auto|0)$/.test(v)))}
function restore(){try{let rules:LayoutRule[]=JSON.parse(localStorage.getItem(key)||'[]');if(!valid(rules))return [];if(key==='clash-android-component-layout-v1'){for(const [marker,preset,backup] of [['clash-android-compact-baseline-v1',adoptedAndroidLayout,'-before-compact-v1'],['clash-android-spacing-baseline-v1',spacingLayout,'-before-spacing-v1'],['clash-android-state-baseline-v1',stateLayout,'-before-state-v1'],['clash-android-position-baseline-v1',positionLayout,'-before-position-v1'],['clash-android-device-test-baseline-v1',deviceTestLayout,'-before-device-test-v1']] as const){if(localStorage.getItem(marker))continue;const remaining=rules.filter(rule=>!preset.rules.some(adopted=>adopted.surface===rule.surface&&adopted.page===rule.page&&adopted.selector===rule.selector&&JSON.stringify(Object.entries(adopted.styles).sort())===JSON.stringify(Object.entries(rule.styles).sort())));if(remaining.length!==rules.length){localStorage.setItem(key+backup,JSON.stringify(rules));localStorage.setItem(key,JSON.stringify(remaining))}localStorage.setItem(marker,'1');rules=remaining}}return rules}catch{return []}}
const rules=ref<LayoutRule[]>(restore()),enabled=ref(true),selected=ref<Selection|null>(null),notice=ref('点击元素后拖动；八个边角手柄调整尺寸。')
const currentPage=ref('')
const deleted=computed(()=>rules.value.filter(rule=>rule.surface===props.surface&&rule.page===currentPage.value&&rule.styles.display==='none'))
const search=ref(''),layers=ref<{selector:string;label:string;depth:number;centerX:number;centerY:number}[]>([])
const filtered=computed(()=>layers.value.filter(l=>!search.value||l.label.includes(search.value)))
const history=ref<string[]>([JSON.stringify(rules.value)]),cursor=ref(0)
let editor:ReturnType<typeof createLayoutEditor>|undefined,attached:Document|undefined,loadTarget:HTMLIFrameElement|undefined,connectedSurface:string|undefined,connectedRoot:HTMLElement|undefined
function persist(){try{localStorage.setItem(key,JSON.stringify(rules.value));notice.value='布局已自动保存到本浏览器'}catch{notice.value='无法写入浏览器存储，请导出布局备份'}}
function change(value:LayoutRule[],commit:boolean){rules.value=value;if(commit){const text=JSON.stringify(value);if(history.value[cursor.value]!==text){history.value=history.value.slice(0,cursor.value+1);history.value.push(text);if(history.value.length>100)history.value.shift();cursor.value=history.value.length-1}persist()}}
function connect(){const nextDoc=props.frame?.contentDocument||props.root?.ownerDocument;if(editor&&attached===nextDoc&&connectedSurface===props.surface&&(props.frame||connectedRoot===props.root)){editor.apply();return}connectedSurface=props.surface;connectedRoot=props.root;editor?.destroy();editor=undefined;selected.value=null;emit('selection',null);layers.value=[];attached=props.frame?.contentDocument||props.root?.ownerDocument;if(!attached?.body)return;editor=createLayoutEditor(attached,()=>props.frame?attached?.querySelector<HTMLElement>('#app .desk')||null:props.root||null,{surface:props.surface,rules:()=>rules.value,enabled:()=>enabled.value&&!props.locked,change,select:value=>{currentPage.value=(props.frame?attached?.querySelector<HTMLElement>('#app .desk'):props.root)?.dataset.uiPage||'component';selected.value=value;emit('selection',value);if(!layers.value.length)layers.value=editor?.layers()||[]}})}
function attach(){if(loadTarget)loadTarget.removeEventListener('load',connect);loadTarget=props.frame;loadTarget?.addEventListener('load',connect);connect()}
watch(()=>[props.frame,props.root,props.surface],async()=>{await nextTick();attach()},{flush:'post'})
watch(()=>[enabled.value,props.locked],()=>editor?.apply())
onMounted(attach)
onUnmounted(()=>{loadTarget?.removeEventListener('load',connect);editor?.destroy()})
function undo(delta:number){const next=cursor.value+delta;if(next<0||next>=history.value.length)return;cursor.value=next;rules.value=JSON.parse(history.value[next]);persist();editor?.apply();refreshLayers()}
function number(field:'x'|'y'|'width'|'height',event:Event){const raw=(event.target as HTMLInputElement).value;if(raw==='')return;const value=Number(raw);if(Number.isFinite(value))editor?.setGeometry({[field]:value})}
function save(name:string,body:string,type:string){const url=URL.createObjectURL(new Blob([body],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportSourceBackup(){const saved=localStorage.getItem(key+'-before-'+sourceBaseline);if(saved)save('clash-layout-before-'+sourceBaseline+'.json',JSON.stringify({version:1,rules:JSON.parse(saved),viewport:props.viewport},null,2),'application/json')}
const hasSourceBackup=!!localStorage.getItem(key+'-before-'+sourceBaseline)
function css(){return rules.value.filter(r=>r.surface==='context').map(r=>`.desk[data-ui-page="${r.page}"]${r.selector===':scope'?'':' > '+r.selector} {\n${Object.entries(r.styles).map(([k,v])=>`  ${k}: ${v} !important;`).join('\n')}\n}`).join('\n\n')}
async function importLayout(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>2e6)throw Error('文件超过 2 MB');const value=JSON.parse(await file.text());if(!valid(value.rules))throw Error('布局文件格式不正确');change(value.rules,true);if(Number.isFinite(value.viewport?.width)&&value.viewport.width>=1&&Number.isFinite(value.viewport?.height)&&value.viewport.height>=1)emit('viewport',value.viewport);editor?.apply()}catch(error){notice.value=(error as Error).message}input.value=''}
function typography(key:TypographyKey,value:string|null){editor?.setTypography(key,value)}
function resetTypography(){editor?.resetTypography()}
function deleteSelected(){editor?.remove();refreshLayers()}
function restoreDeleted(selector:string){editor?.restorePath(selector);refreshLayers()}
function refreshLayers(){layers.value=editor?.layers()||[]}
function selectTarget(selector:string){connect();if(selected.value)return;const element=attached?.querySelector<HTMLElement>(selector);if(element)editor?.choose(element)}
defineExpose({selectTarget})
function center(axis:'x'|'y',event:Event){const raw=(event.target as HTMLInputElement).value;if(raw!==''&&Number.isFinite(Number(raw)))editor?.setCenter({[axis]:Number(raw)})}
async function copyCenter(){if(!selected.value)return;try{await navigator.clipboard.writeText(JSON.stringify({centerX:selected.value.centerX,centerY:selected.value.centerY,unit:'CSS px',origin:'画布左上角'}));notice.value='已复制中心点坐标'}catch{notice.value='请从中心坐标输入框手动复制'}}
function exportCoordinates(){const rows=editor?.layers()||[];save('clash-element-coordinates.csv','\ufeff'+[['元素','选择器','中心 X','中心 Y','宽度','高度'],...rows.map(r=>[r.label,r.selector,r.centerX,r.centerY,r.width,r.height])].map(row=>row.map(cell=>'"'+String(cell).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv')}
</script>
<template>
  <section class="lab-designer" aria-label="可视化布局编辑器">
    <div class="lab-designer-bar"><button class="lab-button" :aria-pressed="enabled" :disabled="locked" @click="enabled=true">选择 / 拖动</button><button class="lab-button" :aria-pressed="!enabled" @click="enabled=false">交互预览</button><button class="lab-button" :disabled="locked||cursor===0" @click="undo(-1)">撤销</button><button class="lab-button" :disabled="locked||cursor===history.length-1" @click="undo(1)">重做</button><button class="lab-button" @click="refreshLayers">刷新元素图层</button><span>{{ locked?'组件已锁定，解锁后可编辑':notice }}</span></div>
    <TypographyTools :selection="selected" :disabled="!selected||locked||!enabled" @change="typography" @reset="resetTypography"/>
    <details v-if="deleted.length" class="lab-deleted" open><summary>已删除元素（{{ deleted.length }}）</summary><div v-for="item in deleted" :key="item.selector"><code>{{ item.selector }}</code><button class="lab-button" :disabled="locked||!enabled" @click="restoreDeleted(item.selector)">恢复元素</button></div></details>
    <div class="lab-inspector-grid"><div><label>元素图层<select aria-label="元素图层" size="5" :disabled="locked" @focus="refreshLayers" @change="editor?.selectPath(($event.target as HTMLSelectElement).value)"><option v-for="layer in filtered" :key="layer.selector" :value="layer.selector">{{ '　'.repeat(Math.min(layer.depth-1,4))+layer.label+' · C('+layer.centerX+', '+layer.centerY+')' }}</option></select></label><input v-model="search" aria-label="搜索元素图层" placeholder="搜索文字、按钮、容器类名…"></div><div><p class="lab-selection-label">{{ selected?.label||'点击画布中的任意卡片、文字、按钮或图标选择元素' }}</p><div class="lab-geometry"><label v-for="field in (['x','y','width','height'] as const)" :key="field">{{ {x:'X 位移',y:'Y 位移',width:'元素宽度',height:'元素高度'}[field] }}<input :aria-label="{x:'X 位移',y:'Y 位移',width:'元素宽度',height:'元素高度'}[field]" type="number" step="1" :min="field==='width'||field==='height'?1:undefined" :value="selected?.[field]" :disabled="!selected||locked||!enabled" @input="number(field,$event)"></label></div><div class="lab-center-fields"><label>中心 X<input aria-label="中心 X" type="number" step="0.1" :value="selected?.centerX" :disabled="!selected||locked||!enabled" @input="center('x',$event)"></label><label>中心 Y<input aria-label="中心 Y" type="number" step="0.1" :value="selected?.centerY" :disabled="!selected||locked||!enabled" @input="center('y',$event)"></label><button class="lab-button" :disabled="!selected" @click="copyCenter">复制中心坐标</button></div><div class="lab-designer-bar"><button class="lab-button" :disabled="!selected||locked" @click="editor?.selectParent()">选中父级</button><button class="lab-button" :disabled="!selected||locked" @click="editor?.reset()">重置当前元素</button><button class="lab-button lab-delete" :disabled="!selected||locked||!enabled||selected.selector===':scope'" @click="deleteSelected">删除元素</button></div></div><div class="lab-layout-export"><button class="lab-button" :disabled="locked" @click="change([],true);editor?.apply()">恢复正式源码布局</button><button v-if="hasSourceBackup" class="lab-button" @click="exportSourceBackup">导出更新前布局备份</button><button class="lab-button" @click="exportCoordinates">导出本页元素坐标 CSV</button><button class="lab-button" @click="save('clash-component-layout.json',JSON.stringify({version:1,rules,viewport},null,2),'application/json')">导出布局 JSON</button><button class="lab-button" @click="save('clash-component-layout.css',css(),'text/css')">导出正式页面 CSS</button><label class="lab-button">导入布局<input type="file" accept=".json" hidden :disabled="locked" @change="importLayout"></label><small>拖动改变视觉位置；宽高参与实际排版。方向键移动 1 px，Shift 移动 10 px，Delete 删除选中元素。删除可撤销或从已删除列表恢复。修改保存在工坊，导出的 CSS 可用于正式页面。</small></div></div>
  </section>
</template>
